function mountEditor(){
    const host=$('#editor-host');if(!host)return;
    if(S.editorMode==='source'){host.innerHTML=`<textarea id="html-source" class="editor-source" aria-label="HTML source" spellcheck="false">${E(S.draft.html)}</textarea>`;$('#html-source').oninput=()=>{S.dirty=true;S.draft.html=$('#html-source').value;};return;}
    const toolbar=`<div class="format-toolbar" role="toolbar" aria-label="Email formatting"><select id="format-block" aria-label="Text style"><option value="p">Paragraph</option><option value="h1">Heading 1</option><option value="h2">Heading 2</option></select>${[['bold','B','Bold'],['italic','<i>I</i>','Italic'],['underline','<u>U</u>','Underline'],['insertUnorderedList','&#8226;','Bulleted list'],['justifyLeft','&#9776;','Align left'],['justifyCenter','&#8801;','Align centre'],['undo','&#8630;','Undo'],['redo','&#8631;','Redo']].map(([key,label,name])=>`<button class="icon-btn" data-action="format" data-value="${key}" title="${name}" aria-label="${name}">${label}</button>`).join('')}<span class="tool-divider"></span><button class="icon-btn" data-action="insert-link" aria-label="Insert link" title="Link">${icon('link')}</button><button class="icon-btn" data-action="insert-image" aria-label="Insert image" title="Image">${icon('image')}</button><button class="btn small" data-action="insert-button">Button</button><button class="btn small" data-action="insert-table">Table</button></div>`;
    host.innerHTML=(S.editorMode==='visual'?toolbar:'')+`<div class="editor-canvas ${S.device==='mobile'?'mobile':''}"><iframe id="email-frame" title="Email ${S.editorMode==='visual'?'design editor':'preview'}" sandbox="${S.editorMode==='visual'?'allow-same-origin':''}"></iframe></div>`;
    const frame=$('#email-frame');frame.srcdoc=previewHTML(LIB.prepare(S.draft.html,{brand:S.brand,preheader:$('#draft-preheader')?.value||S.draft.preheader,editing:S.editorMode==='visual'}));
    if(S.editorMode==='visual'){
        frame.onload=()=>{const doc=frame.contentDocument;if(!doc)return;doc.body.contentEditable='true';doc.querySelectorAll('[data-tz-header],[data-tz-footer]').forEach(n=>n.contentEditable='false');doc.addEventListener('input',()=>{S.dirty=true;S.draft.html=LIB.serialize(doc);if($('#save-state'))$('#save-state').textContent='Unsaved changes';});doc.addEventListener('click',e=>{
            if(e.target.closest('a'))e.preventDefault();
            if(e.target.closest('[data-tz-header],[data-tz-footer]'))return;
            const target=e.target.closest('img,[data-tz-placeholder="image"]');if(!target)return;e.preventDefault();
            const current=target.tagName==='IMG'?target.getAttribute('src')||'':'https://';
            const url=prompt('HTTPS image URL. Leave empty to remove this image.',current);if(url===null)return;
            if(!url.trim())target.remove();else{
                if(!LIB.safeHttps(url.trim())){toast('Use a complete HTTPS image URL.');return;}
                const alt=prompt('Describe the image for readers who cannot see it.',target.getAttribute('alt')||'');if(alt===null)return;
                const img=doc.createElement('img');img.src=url.trim();img.alt=alt;img.width=Number(target.getAttribute('width'))||520;
                img.style.cssText=`display:block;width:100%;max-width:${img.width}px;height:auto;border:0;border-radius:4px`;target.replaceWith(img);
            }
            S.draft.html=LIB.serialize(doc);S.dirty=true;if($('#save-state'))$('#save-state').textContent='Unsaved changes';
        });};
        $('#format-block').onchange=e=>format('formatBlock',e.target.value);
        $$('.format-toolbar button').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()));
    }
}
function format(command,value){const frame=$('#email-frame');const doc=frame?.contentDocument;if(!doc)return;frame.contentWindow.focus();doc.execCommand(command,false,value);S.draft.html=LIB.serialize(doc);S.dirty=true;}
